use super::*;

/// A profile shaped as UVtools bundles them, with the panel and notes
/// given.
fn ini(panel: &str, notes: &str) -> String {
    format!(
        "# generated by PrusaSlicer 2.9.0\n\
{panel}\n\
display_mirror_y = 0\n\
display_orientation = landscape\n\
max_print_height = 220\n\
printer_model = SL1\n\
printer_notes = Don't remove the following keywords!\\nPRINTER_VENDOR_PRUSA3D\\nPRINTER_MODEL_SL1\\n{notes}\\n\\nSTART_CUSTOM_VALUES\\nLiftHeight_8\\nEND_CUSTOM_VALUES\n"
    )
}

const SATURN_4_PANEL: &str = "display_width = 218.88\n\
display_height = 122.88\n\
display_pixels_x = 11520\n\
display_pixels_y = 5120\n\
display_mirror_x = 1";

fn entry(title: &str, notes: &str) -> CatalogEntry {
    let path = PathBuf::from(format!("{title}.ini"));
    CatalogEntry::from_ini(&path, &IniFile::parse(&ini(SATURN_4_PANEL, notes))).unwrap()
}

fn format_of(notes: &str) -> String {
    entry("Elegoo Saturn 4", notes).binding().to_string()
}

#[test]
fn a_profile_states_its_panel_mirror_height_and_file() {
    let entry = entry("Elegoo Saturn 4", "FILEFORMAT_GOO");

    assert_eq!((entry.pixels_x, entry.pixels_y), (11520, 5120));
    assert_eq!((entry.width.value, entry.depth.value), (218.88, 122.88));
    assert_eq!(entry.mirror, Mirror { x: true, y: false });
    assert_eq!(entry.height_mm, 220.0);
    assert!(entry.landscape);
    assert_eq!(entry.file_format.as_deref(), Some("GOO"));
    assert_eq!(entry.brand_and_model(), Some(("Elegoo", "Saturn 4")));
}

#[test]
fn the_hardware_derives_the_pixel_from_the_panel() {
    let hardware = entry("Elegoo Saturn 4", "FILEFORMAT_GOO")
        .hardware(Path::new("x.ini"))
        .unwrap();

    assert_eq!(hardware.pixel_size_microns().x.value(), 19.0);
    assert_eq!(hardware.pixel_size_microns().y.value(), 24.0);
    assert_eq!(hardware.build_volume().z_mm(), 220.0);
    assert!(hardware.mirror().x);
}

#[test]
fn a_profile_missing_its_panel_is_refused_by_key() {
    let text = ini("display_width = 218.88", "FILEFORMAT_GOO");
    let err = CatalogEntry::from_ini(Path::new("a.ini"), &IniFile::parse(&text)).unwrap_err();

    assert!(
        matches!(
            err,
            UvtoolsCatalogError::MissingValue {
                key: "display_height",
                ..
            }
        ),
        "{err}"
    );
}

#[test]
fn a_mirror_that_is_neither_on_nor_off_is_refused() {
    let panel = SATURN_4_PANEL.replace("display_mirror_x = 1", "display_mirror_x = yes");
    let text = ini(&panel, "FILEFORMAT_GOO");
    let err = CatalogEntry::from_ini(Path::new("a.ini"), &IniFile::parse(&text)).unwrap_err();

    assert!(
        matches!(
            err,
            UvtoolsCatalogError::BadValue {
                key: "display_mirror_x",
                ..
            }
        ),
        "{err}"
    );
}

#[test]
fn uvtools_own_profiles_drop_its_name() {
    let entry = entry("UVtools Prusa SL1S SPEED", "");

    assert_eq!(entry.brand_and_model(), Some(("Prusa", "SL1S SPEED")));
}

#[test]
fn ctb_takes_the_stated_revision_or_uvtools_default() {
    assert_eq!(format_of("FILEFORMAT_CTB\\nFILEVERSION_3"), "ctb@v3");
    assert_eq!(format_of("FILEFORMAT_CTB"), "ctb@v5");
    assert_eq!(format_of("FILEFORMAT_ENCRYPTED.CTB"), "ctb@v5enc");
}

#[test]
fn goo_takes_the_stated_revision_or_uvtools_default() {
    assert_eq!(format_of("FILEFORMAT_GOO"), "goo@v3.0");
    assert_eq!(format_of("FILEFORMAT_GOO\\nFILEVERSION_51"), "goo@v5.1");
}

#[test]
fn cxdlp_takes_uvtools_default_revision() {
    assert_eq!(format_of("FILEFORMAT_CXDLP"), "cxdlp@v3");
}

#[test]
fn anycubic_files_are_named_by_their_extension() {
    assert_eq!(format_of("FILEFORMAT_PWMX\\nFILEVERSION_516"), "aff@pwmx");
    assert_eq!(format_of("FILEFORMAT_M5SP"), "aff@m5sp");
    assert_eq!(format_of("FILEFORMAT_PWSZ"), "azf@pwsz");
    assert_eq!(format_of("FILEFORMAT_PM4U"), "azf@pm4u");
}

#[test]
fn a_format_this_workspace_does_not_know_keeps_its_extension() {
    let binding = entry("Nova3D Whale", "FILEFORMAT_RGB.CWS").binding();

    assert_eq!(binding.format, FormatKind::Unknown("rgb.cws".to_owned()));
    assert_eq!(binding.version, None);
    assert_eq!(format_of("FILEFORMAT_PHOTON\\nFILEVERSION_2"), "photon@v2");
    assert_eq!(
        format_of("FILEFORMAT_ZIP\\nFILECLASS_KLIPPER"),
        "zip@klipper"
    );
}

#[test]
fn a_profile_naming_no_file_writes_prusaslicers_archive() {
    assert_eq!(format_of(""), "sl1@sl1");
}

#[test]
fn a_figure_states_what_rounds_to_it() {
    let figure = Figure::parse("223.642").unwrap();

    assert!(figure.states(223.6416));
    assert!(figure.states(223.642));
    assert!(!figure.states(223.64));
    assert!(Figure::parse("250").unwrap().states(250.0));
    assert!(!Figure::parse("250").unwrap().states(249.7));
}

#[test]
fn a_length_that_is_not_positive_is_no_figure() {
    assert_eq!(Figure::parse("0"), None);
    assert_eq!(Figure::parse("-1.5"), None);
    assert_eq!(Figure::parse("wide"), None);
}

#[test]
fn creality_model_codes_leave_the_name() {
    assert_eq!(model_name("Creality", "Halot One CL-60"), "Halot One");
    assert_eq!(model_name("Creality", "Halot Lite CL-89L"), "Halot Lite");
    assert_eq!(model_name("Creality", "Halot Ray CL925"), "Halot Ray");
    assert_eq!(model_name("Creality", "Halot X1"), "Halot X1");
    assert_eq!(model_name("Creality", "CT-005 Pro"), "CT-005 Pro");
    assert_eq!(model_name("Creality", "LD-002H"), "LD-002H");
}

#[test]
fn a_variant_suffix_reads_as_a_parenthesis() {
    assert_eq!(
        model_name("Voxelab", "Proxima 6 - SVGX"),
        "Proxima 6 (SVGX)"
    );
    assert_eq!(model_name("Uniz", "IBEE (Klipper)"), "IBEE (Klipper)");
}

#[test]
fn a_family_is_the_series_the_name_opens_with() {
    assert_eq!(family_of("Sonic Mini 8K S"), "Sonic");
    assert_eq!(family_of("Bene4 Mono"), "Bene");
    assert_eq!(family_of("Shadow5.5"), "Shadow");
    assert_eq!(family_of("CT-005 Pro"), "CT");
    assert_eq!(family_of("GKone"), "GKone");
    assert_eq!(family_of("X10 4K Mono"), "X10");
    assert_eq!(family_of("I-Box Mono"), "I-Box");
}

#[test]
fn a_profile_without_a_library_is_not_read() {
    let err = UvtoolsCatalogReader::without_a_library()
        .read(&[Path::new("nowhere")])
        .unwrap_err();

    assert!(
        matches!(err, UvtoolsCatalogError::NoPrinterLibrary),
        "{err}"
    );
    assert!(err.to_string().contains("--printer-library"), "{err}");
}
